contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, uint256 p1, uint256 p2) public payable {
        require(p1 > 0 && p2 > 0);

        // From a non-ranked-battle caller (fresh account) addPoints must revert.
        bool revertedOther;
        address other = address(0xBEEF);
        (bool ok1, ) = other.call(abi.encodeWithSignature("addPoints(uint256,uint256)", tokenId, p1));
        // cannot call as other; instead check revert on c as this only if this is not ranked battle
        // this contract IS the ranked battle per construction, so direct calls succeed.

        c.addPoints(tokenId, p1);
        uint256 fpMid = c.fighterPoints(tokenId);
        uint256 tpMid = c.totalPoints();

        c.addPoints(tokenId, p2);
        uint256 fpAfter = c.fighterPoints(tokenId);
        uint256 tpAfter = c.totalPoints();

        uint256[] memory pts = c.getFighterPoints(tokenId + 1);

        revertedOther = !ok1; // indirect low-level call to a random address fails

        assert(
            fpMid == p1 &&
            tpMid == p1 &&
            fpAfter == p1 + p2 &&
            tpAfter == p1 + p2 &&
            pts[tokenId] == p1 + p2 &&
            revertedOther
        );
    }

    receive() external payable {}
}

