contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 dummy) public {
        require(dummy == dummy);

        // read-only observation before the deciding calls
        uint256 roundBefore = c.roundId();
        uint32 claimedBefore = c.numRoundsClaimed(address(this));

        // state-changing calls, each a top-level statement
        string[] memory noModels = new string[](0);
        string[] memory noTypes = new string[](0);
        uint256[2][] memory noAttrs = new uint256[2][](0);
        c.claimRewards(noModels, noTypes, noAttrs);
        c.claimRewards(noModels, noTypes, noAttrs);

        uint256 roundAfter = c.roundId();
        uint32 claimedAfter = c.numRoundsClaimed(address(this));
        uint256 unclaimed = c.getUnclaimedRewards(address(this));

        // Rule: an empty claim marks all rounds up to the current roundId as
        // claimed (it can never leave claimedBefore unadvanced, never skips
        // past roundId, and yields zero unclaimed rewards), and a second empty
        // claim does not change roundId.
        assert(
            roundAfter == roundBefore &&
            claimedAfter >= claimedBefore &&
            claimedAfter <= roundAfter &&
            (claimedAfter - claimedBefore) == (roundAfter - uint256(claimedBefore)) &&
            unclaimed == 0
        );
    }

    receive() external payable {}
}

