contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 wrongLength) public {
        // Fresh deployment: roundId starts at 0 and no round has been selected.
        require(wrongLength != c.winnersPerPeriod(), "length must mismatch");
        require(!c.isSelectionComplete(0), "round must be unselected");

        uint256 roundBefore = c.roundId();
        bool reverted;
        // Call with an array of the wrong length; it must revert (either at the
        // admin check or at the length check, but never reach selection).
        if (wrongLength == 0) {
            try c.pickWinner(new uint256[](0)) { reverted = false; } catch { reverted = true; }
        } else if (wrongLength == 1) {
            uint256[] memory w = new uint256[](1);
            try c.pickWinner(w) { reverted = false; } catch { reverted = true; }
        } else {
            uint256[] memory w = new uint256[](wrongLength);
            try c.pickWinner(w) { reverted = false; } catch { reverted = true; }
        }

        assert(
            reverted &&
            c.roundId() == roundBefore &&
            !c.isSelectionComplete(roundBefore)
        );
    }

    receive() external payable {}
}

